Q() { docker exec supabase_db_test psql -U postgres -d postgres -Atc "$1"; }
echo '--- functions mentioning dg_account/metadata/PlatformAccount'; Q "select p.oid::regprocedure, p.prosecdef, p.proconfig, p.proacl from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and (p.prosrc ilike '%PlatformAccount%' or p.prosrc ilike '%dg_account%' or p.prosrc ilike '%my_accounts%')";
echo '--- policies mentioning'; Q "select schemaname, tablename, policyname, cmd, qual, with_check from pg_policies where coalesce(qual,'')||coalesce(with_check,'') ilike any(array['%PlatformAccount%','%dg_account%','%my_accounts%'])";
echo '--- views mentioning'; Q "select c.relname, c.reloptions, pg_get_viewdef(c.oid) ilike '%dg_account%' as dg, pg_get_viewdef(c.oid) ilike '%PlatformAccount%' as pa from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('v','m')";
echo '--- col privs'; Q "select grantee, privilege_type, string_agg(column_name, ',') from information_schema.column_privileges where table_schema='public' and table_name='PlatformAccount' group by 1,2 order by 1,2";
echo '--- table privs'; Q "select grantee, string_agg(privilege_type, ',') from information_schema.role_table_grants where table_schema='public' and table_name in ('PlatformAccount') group by 1"; Q "select table_name, grantee, string_agg(privilege_type, ',') from information_schema.role_table_grants where table_schema='public' and table_name='my_accounts' group by 1,2";
echo '--- fn acl'; Q "select oid::regprocedure, proacl from pg_proc where proname in ('author_of_content','author_of_concept','my_platform_account_ids')";
echo '--- migrations tail'; ls packages/database/supabase/migrations | tail -12; Q "select version from supabase_migrations.schema_migrations order by 1 desc limit 8";

